<script>
import Layout from "../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";
import moment from "moment";
import { Dropdown } from "bootstrap";
import ReportsHeader from "@/components/reports-header";

export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
    ReportsHeader,
  },
  data() {
    return {
      currenTotal: 0,
      day: moment(new Date(Date.now())).format("YYYY-MM-DD"),
      payid: [],
      final_total: [],
      billing_invoices: [],
      customerData: [],
      page: 1,
      total: 0,
      status: 1,
      limit: 50,
      pay_amount: 0,
      total_amount: 0,
      tot_pages: 0,
      BillingInvoicesSearchMode: false,
      resultStatus: null,
      searchModel: "",
      billing_invoices_id: [],
      x: [],
      customerInfo: [],
      search: "",
      selectedCustomers: null,
      bill: [],
      allSelected: false,
      searchInput: null,
      customer_id: null,
      branch_id: null,
      customer_bill_id: null,
      dropdown: null,
      filter: "all",
      filter_title: { name_en: "All", name: "الكل" },
      filter_pay: "",
      filterdPeriod: "During of ",
      date: {
        to: "",
      },
      tariffs: [],
      existingSalaryMonthes: [],
      // appprices:[]
    };
  },
  computed: {
    filteredCountries() {
      return this.customerInfo
        .filter((customerInfo) => {
          console.log(this.customerInfo);
          if (customerInfo.name.includes(this.search)) {
            console.log("mohamed test");
            console.log(customerInfo.name);
            return customerInfo.name;
          } else if (customerInfo.account_no == this.search) {
            return customerInfo.name;
          } else if (customerInfo.meter_no == this.search) {
            return customerInfo.name;
          }
        })
        .map((customerInfo) => {
          return (
            customerInfo.id +
            "-" +
            "(" +
            customerInfo.meter_no +
            ")" +
            "-" +
            customerInfo.name
          );
        });
    },
    generate() {
      return this.final_total
        .map((c) => {
          console.log("total", c.customer.tariff.fees);
          return c.customer.tariff.fees;
        })
        .reduce((a, b) => {
          this.total = parseInt(a) + parseInt(b);
          return this.total;
        }, 0);
    },
    pages() {
      const range = [];
      const start = Math.max(2, this.page - 2);
      const end = Math.min(this.tot_pages - 1, this.page + 2);

      for (let i = start; i <= end; i++) {
        range.push(i);
      }

      return range;
    },
  },
  methods: {
    getExistingMonth() {
      this.http.get("billing-invoices/exitsingMonthes").then((res) => {
        if (res.status) {
          this.existingSalaryMonthes = res.data.map((m) => ({
            label: m,
            value: m,
          }));
        }
      });
    },
    monthlyBilling() {
      console.log("fyou");

      var data = {
        title: "popups.generate_monthly_invoices",
        inputs: [
          {
            model: "month",
            type: "select",
            options: this.existingSalaryMonthes,
            label: "emps.payment_details.month",
          },
        ],
        buttons: [
          {
            text: "popups.generate_invoices",
            closer: true,
            color: "primary",
            handler: (obj = {}) => {
              console.log(obj);

              obj.branch_id = this.branch_id;
              this.$loading.show();
              if (obj.month)
                this.http
                  .post("monthly-billing", {
                    month: obj.month.split("-")[1],
                    year: obj.month.split("-")[0],
                  })
                  .then(() => {
                    this.$loading.hide();
                    this.searchBillingInvoices(1);
                  });
              else
                this.popup.alert({
                  title: this.$t("popups.usersErrorTitle"),
                  msg: this.$t("popups.please_select_month"),
                });
            },
          },
          {
            text: "popups.cancel",
            closer: true,
            color: "danger",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.modal(data);
    },
    get(page) {
      if (this.date.to && this.date.from) {
        this.filterdPeriod = `
        ${moment(this.date.from).endOf("month").format("YYYY-MM-DD")}  - 
        ${moment(this.date.to).endOf("month").format("YYYY-MM-DD")}  `;
      } else if (this.date.to)
        this.filterdPeriod = `${moment(this.date.to)
          .endOf("month")
          .format("YYYY-MM-DD")}`;
      else if (this.date.from)
        this.filterdPeriod = `${moment(this.date.from)
          .endOf("month")
          .format("YYYY-MM-DD")}`;
      else this.filterdPeriod = "";

      console.log(page);

      this.http
        .post("billing-invoices/pagination", {
          limit: this.limit,
          page: page,
          filter: this.filter,
          date: {
            to: this.date.to
              ? moment(this.date.to)
                  .add(-1, "months")
                  .endOf("month")
                  .format("YYYY-MM-DD")
                  .toString()
              : "",
            from: this.date.from
              ? moment(this.date.from)
                  .add(-1, "months")
                  .endOf("month")
                  .format("YYYY-MM-DD")
                  .toString()
              : "",
          },
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.billing_invoices = res.data;
          this.getExistingMonth();
        });
    },
    searchBillingInvoices(page) {
      // if (!this.search.length) return this.get(page);

      if (this.date.to && this.date.from) {
        this.filterdPeriod = `
        ${moment(this.date.from).endOf("month").format("YYYY-MM-DD")}  - 
        ${moment(this.date.to).endOf("month").format("YYYY-MM-DD")}  `;
      } else if (this.date.to)
        this.filterdPeriod = `${moment(this.date.to)
          .endOf("month")
          .format("YYYY-MM-DD")}`;
      else if (this.date.from)
        this.filterdPeriod = `${moment(this.date.from)
          .endOf("month")
          .format("YYYY-MM-DD")}`;
      else this.filterdPeriod = "";

      console.log("ffffffffff", page, this.filter, this.pay, this.date);
      this.http
        .post("billing-invoices/search-invoices", {
          limit: this.limit,
          page: page,
          filter: this.filter,
          pay: this.filter_pay,
          search: this.search,
          date: {
            to: this.date.to
              ? moment(this.date.to)
                  .add(-1, "months")
                  .endOf("month")
                  .format("YYYY-MM-DD")
                  .toString()
              : "",
            from: this.date.from
              ? moment(this.date.from)
                  .add(-1, "months")
                  .endOf("month")
                  .format("YYYY-MM-DD")
                  .toString()
              : "",
          },
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.billing_invoices = res.data;
          this.getExistingMonth();
          console.log("searchBillingInvoices", this.billing_invoices);
        });
    },
    getTariffs() {
      this.http.get("tariff").then((res) => {
        if (res.status) this.tariffs = res.data;
      });
    },

    reset() {
      this.date = {};
      this.filterdPeriod = "";
      this.selectedPaymentStatus = null;
      this.selectedPayMethod = null;
      this.filter = "all";
      this.filter_pay = "";
      this.filter_title = { name_en: "All", name: "الكل" };
      this.searchBillingInvoices(1);
    },
    goToPage(p) {
      if (p < 1 || p > this.tot_pages) return;
      this.searchBillingInvoices(p);
    },
  },

  created() {
    const current_user = JSON.parse(localStorage.currentUser);
    this.branch_id = current_user.branch_id;
    console.log("bid", this.branch_id);

    // this.get(1);
    this.searchBillingInvoices(1);
    this.getTariffs();
    this.getExistingMonth();
    // this.selectedCustomer()
    //  this.getBillingInvoices()
  },
  mounted() {
    this.dropdown = new Dropdown(".dropdown-toggle.filter-assets");
  },
};
</script>

